  "prediction_basis_card_ids": ["C19", "C54", "C57", "C44", "C09", "C20"],
  "claims": [
    {
      "claim": "Cefuroxime axetil, the closest cephem prodrug analog sharing the cephem core, C3 carbamoyloxymethyl, and acyloxyalkyl ester prodrug motif, had measured human absolute oral bioavailability of 64% (90% CI 58-69%) after a 500 mg oral dose, directly supporting F >= 20% for this prodrug class.",
      "card_ids": ["C19"]
    },
    {
      "claim": "Cefuroxime axetil is a PEPT1 substrate and its prodrug design leverages PEPT1-mediated uptake; cefixime and cefadroxil are also PEPT1 substrates, supporting carrier-mediated intestinal uptake as a class feature relevant to cephem prodrugs.",
      "card_ids": ["C54", "C57", "C55", "C61"]
    },
    {
      "claim": "Atenolol, a low-permeability Caco-2 marker with Papp around 4-8 x 10^-7 cm/s and 2.12 x 10^-6 cm/s in IEC layers, has human oral bioavailability of about 50-63%, showing low in vitro permeability does not imply F below 20%.",
      "card_ids": ["C09", "C20", "C63"]
    },
    {
      "claim": "Amorphous cefuroxime axetil achieved 100% dissolution within 60 minutes, supporting adequate dissolution for the ester prodrug.",
      "card_ids": ["C44"]
    },
    {
      "claim": "L6 hepatic esterase metabolism records for oseltamivir and cephapirin/cephalothin indicate ester prodrugs undergo presystemic ester hydrolysis, but this is the expected activation pathway and does not contradict the high F observed for cefuroxime axetil.",
      "card_ids": ["C67", "C73"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C67", "C73"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query molecule.",
    "The query differs from cefuroxime axetil at C7 (hydroxyethyl versus furan methoxyimino acetamido) and in ester alkyl (acetoxymethyl versus 1-acetoxyethyl); impact on PEPT1 affinity, permeability, and esterase stability is unmeasured.",
    "No query-specific PEPT1 transport, efflux, intestinal metabolism, or hepatic clearance data are available.",
    "L6 hepatic esterase records are for other ester prodrugs/cephems (oseltamivir, cephapirin/cephalothin) and do not provide quantitative clearance for the query.",
    "The endpoint for the prodrug (intact ester versus active acid) is not explicitly defined; if intact prodrug is the measured species, ester hydrolysis could lower F, but human cefuroxime axetil F=64% was measured as active cefuroxime."
  ],
  "decision_summary": "Predicted high because the closest transferable human record (cefuroxime axetil F=64%) and all human beta-lactam F records support F >= 20%; L6 hepatic esterase metabolism records are mechanistically relevant but do not provide affirmative threshold-relevant evidence for F < 20% and do not overturn the high prediction."
}

